"""Verify starter contents; refresh with ``python3 -m starter.manifest``."""

import hashlib
import json
import re
import subprocess
from pathlib import Path

from starter.cleanup import CACHE_PATHS, STARTER_PATHS, StarterError

MANIFEST = ".starter-manifest.json"


def cache_file(path: Path) -> bool:
    """Recognize only Python-generated bytecode, not arbitrary cache files."""
    return path.parent.name == "__pycache__" and re.fullmatch(
        r"[A-Za-z_][\w]*\.cpython-\d+(?:\.opt-\d+)?\.pyc", path.name
    ) is not None


def inventory(root: Path) -> dict[str, str]:
    """Hash starter files without following links or including caches."""
    result: dict[str, str] = {}
    for name in STARTER_PATHS + CACHE_PATHS:
        if name in {MANIFEST, ".git"}:
            continue
        entry = root / name
        paths = [entry] if not entry.is_dir() else [entry, *entry.rglob("*")]
        for path in paths:
            relative = path.relative_to(root).as_posix()
            if path.is_symlink():
                raise StarterError(f"symlink is not a starter file: {relative}")
            if path.is_file() and not cache_file(path):
                result[relative] = hashlib.sha256(path.read_bytes()).hexdigest()
            elif path.exists() and not path.is_dir() and not path.is_file():
                raise StarterError(f"unsupported starter entry: {relative}")
    return result


def verify(root: Path) -> None:
    """Refuse deletion unless both the manifest and Git state are clean."""
    manifest = root / MANIFEST
    if manifest.is_symlink() or not manifest.is_file():
        raise StarterError("starter manifest missing or symlinked; use --output")
    expected = json.loads(manifest.read_text(encoding="utf-8"))
    if not isinstance(expected, dict) or not expected:
        raise StarterError("invalid starter manifest; use --output")
    actual = inventory(root)
    changed = sorted(
        name for name in expected.keys() | actual.keys()
        if expected.get(name) != actual.get(name)
    )
    # Empty foreign directories also belong to the user.
    allowed_dirs = {
        parent.as_posix()
        for name in expected
        for parent in Path(name).parents
    }
    for name in STARTER_PATHS + CACHE_PATHS:
        if name == ".git":
            continue
        entry = root / name
        if entry.is_dir():
            for directory in [entry, *entry.rglob("*")]:
                relative = directory.relative_to(root).as_posix()
                if (directory.is_dir() and relative not in allowed_dirs
                        and directory.name != "__pycache__"):
                    changed.append(relative)
    if changed:
        raise StarterError(
            "starter contents differ: " + ", ".join(sorted(set(changed)))
            + "; preserve these files or use --output"
        )
    git = root / ".git"
    if git.is_symlink() or (git.exists() and not git.is_dir()):
        raise StarterError("linked worktrees are unsupported; use --output")
    if git.is_dir():
        result = subprocess.run(
            ["git", "status", "--porcelain", "--untracked-files=all"],
            cwd=root, capture_output=True, text=True, check=False,
        )
        if result.returncode or result.stdout.strip():
            raise StarterError(
                "starter Git checkout is not clean; use --output\n"
                + result.stdout + result.stderr
            )


def main() -> None:
    """Deliberately refresh the shipped inventory after starter edits."""
    root = Path(__file__).resolve().parents[1]
    (root / MANIFEST).write_text(
        json.dumps(inventory(root), indent=2, sort_keys=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
